mapper.select:
select a.id, a.task_type, a.task_status, a.tray_id, a.tray_code, a.location_id, a.`result` , a.task_no, a.purpose_position, a.start_position, a.receive_time, a.start_time, a.end_time, a.error_code, a.error_message, a.current_line_number, a.request_count, a.send_data, a.accept_data, a.remark, a.create_by, a.create_time,a.main_task_no
,tl.name as locationName,tl.extention_type ,a.delivery_type,a.priority,tr.status as trayStatus
from t_task_wcs a
left join t_location tl on a.location_id = tl.id
left join t_tray tr on a.tray_id = tr.id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.task_type = #{taskType}
    and a.task_status = #{taskStatus}
    and a.tray_id = #{trayId}
    and a.tray_code like concat('%', #{trayCode}, '%')

    and a.location_id = #{locationId}
    and a.result = #{result}
    and a.task_no = #{taskNo}
    and a.purpose_position =
        #{purposePosition}

    and a.start_position = #{startPosition}

    and a.receive_time = #{receiveTime}
    and a.start_time = #{startTime}
    and a.end_time = #{endTime}
    and a.error_code like concat('%', #{errorCode}, '%')
    and a.error_message = #{errorMessage}
    and a.current_line_number = #{currentLineNumber}
    and a.request_count = #{requestCount}
    and a.send_data = #{sendData}
    and a.accept_data = #{acceptData}


${params.dataScope}
order by a.task_status = '2' desc,a.priority desc,a.create_time desc

mapper.update:
update t_task_wcs set task_status = #{taskWcs.taskStatus}
 ,location_id = #{taskWcs.locationId}
 where id in

    #{id}

mapper.select:
select t.*, m.code materialCode, m.name materialName from (select tw.task_no taskNo, tw.id id, l.name locationName, r.name reservoirName, tw.task_status taskStatus, tw.task_type taskType, (case tw.task_status when '1' then null else tw.create_by end) createBy, (case tw.task_status when '1' then null else tw.create_time end) createTime, (case twd.type when '1' then ti.material_id when '2' then tto.material_id when '5' then td.material_id else null end) materialId, (case twd.type when '1' then ti.predict_count when '2' then tto.predict_count when '5' then td.predict_count else null end) predictCount, (case twd.type when '1' then ti.actual_count when '2' then tto.actual_count when '5' then td.actual_count else null end) actualCount, (case twd.type when '1' then ti.batch_code else null end) batchCode from t_task_wcs tw left join t_task_wcs_detail twd on twd.task_id=tw.id left join t_task_in ti on ti.id=twd.origin_id left join t_task_out tto on tto.id=twd.origin_id left join t_task_detail td on td.id=twd.origin_id left join t_location l on l.id=tw.location_id left join t_reservoir r on r.id=l.reservoir_id where tw.del_flag='0'
and tw.task_no like concat('%',#{taskNo},'%')
and tw.task_status =#{taskStatus}
) t left join t_material m on m.id=t.materialId where 1=1
and m.name like concat('%',#{materialName},'%')
order by t.id desc
